CREATE TABLE IF NOT EXISTS offers (id TEXT PRIMARY KEY,title TEXT NOT NULL,price REAL NOT NULL,original_price REAL,discount REAL NOT NULL DEFAULT 0,rating REAL,sales INTEGER,shop TEXT,image_url TEXT NOT NULL,destination TEXT NOT NULL,source TEXT NOT NULL,category TEXT,published_at INTEGER NOT NULL,coupon_code TEXT,coupon_condition TEXT,coupon_expires_at INTEGER,payment_label TEXT,cataloged_at INTEGER,last_checked_at INTEGER,last_seen_at INTEGER,availability TEXT NOT NULL DEFAULT 'active',refresh_failures INTEGER NOT NULL DEFAULT 0,price_changed_at INTEGER);
CREATE INDEX IF NOT EXISTS idx_offers_published ON offers(published_at DESC);
CREATE INDEX IF NOT EXISTS idx_offers_category_published ON offers(category,published_at DESC);
CREATE INDEX IF NOT EXISTS idx_offers_shop_published ON offers(shop,published_at DESC);
CREATE INDEX IF NOT EXISTS idx_offers_availability_checked ON offers(availability,last_checked_at);
CREATE INDEX IF NOT EXISTS idx_offers_cataloged ON offers(cataloged_at DESC);
CREATE TABLE IF NOT EXISTS clicks (offer_id TEXT NOT NULL,clicked_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS idx_site_clicks_time ON clicks(clicked_at);
CREATE TABLE IF NOT EXISTS coupons (id TEXT PRIMARY KEY,source TEXT NOT NULL,code TEXT NOT NULL,title TEXT,kind TEXT NOT NULL DEFAULT 'code',condition TEXT,destination TEXT NOT NULL,active_at INTEGER,expires_at INTEGER,published_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS idx_coupons_expires_published ON coupons(expires_at,published_at DESC);
CREATE TABLE IF NOT EXISTS store_links (slug TEXT PRIMARY KEY,name TEXT NOT NULL,destination TEXT NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS offer_prices (offer_id TEXT NOT NULL,observed_on TEXT NOT NULL,price REAL NOT NULL,observed_at INTEGER NOT NULL,PRIMARY KEY (offer_id,observed_on));
CREATE INDEX IF NOT EXISTS idx_offer_prices_offer_time ON offer_prices(offer_id,observed_at DESC);
CREATE TABLE IF NOT EXISTS offer_feedback (offer_id TEXT NOT NULL,kind TEXT NOT NULL,quantity INTEGER NOT NULL DEFAULT 0,updated_at INTEGER NOT NULL,PRIMARY KEY (offer_id,kind));
CREATE TABLE IF NOT EXISTS page_views_daily (observed_on TEXT NOT NULL,path TEXT NOT NULL,quantity INTEGER NOT NULL DEFAULT 0,PRIMARY KEY (observed_on,path));
CREATE INDEX IF NOT EXISTS idx_page_views_daily_date ON page_views_daily(observed_on);
CREATE TABLE IF NOT EXISTS traffic_sources_daily (observed_on TEXT NOT NULL,source TEXT NOT NULL,landing_path TEXT NOT NULL,quantity INTEGER NOT NULL DEFAULT 0,PRIMARY KEY (observed_on,source,landing_path));
CREATE INDEX IF NOT EXISTS idx_traffic_sources_daily_date ON traffic_sources_daily(observed_on);
CREATE TABLE IF NOT EXISTS story_assets (id TEXT PRIMARY KEY,image BLOB NOT NULL,created_at INTEGER NOT NULL,expires_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS idx_story_assets_expires ON story_assets(expires_at);
CREATE TABLE IF NOT EXISTS instagram_story_offers (media_id TEXT PRIMARY KEY,container_id TEXT NOT NULL,offer_id TEXT,title TEXT NOT NULL,price REAL,link TEXT NOT NULL,published_at INTEGER NOT NULL,expires_at INTEGER NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS idx_instagram_story_offers_container ON instagram_story_offers(container_id);
CREATE INDEX IF NOT EXISTS idx_instagram_story_offers_time ON instagram_story_offers(published_at DESC);
CREATE TABLE IF NOT EXISTS instagram_dm_events (event_hash TEXT PRIMARY KEY,status TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS idx_instagram_dm_events_time ON instagram_dm_events(created_at);
CREATE TABLE IF NOT EXISTS instagram_story_clicks_daily (observed_on TEXT NOT NULL,media_id TEXT NOT NULL,offer_id TEXT NOT NULL,quantity INTEGER NOT NULL DEFAULT 0,PRIMARY KEY (observed_on,media_id,offer_id));
CREATE INDEX IF NOT EXISTS idx_instagram_story_clicks_date ON instagram_story_clicks_daily(observed_on);
CREATE TABLE IF NOT EXISTS abuse_events (event_key TEXT PRIMARY KEY,expires_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS idx_abuse_events_expires ON abuse_events(expires_at);
CREATE TABLE IF NOT EXISTS blog_posts (id TEXT PRIMARY KEY,slug TEXT NOT NULL UNIQUE,title TEXT NOT NULL,excerpt TEXT NOT NULL,body_markdown TEXT NOT NULL,cover_image_url TEXT,category TEXT,status TEXT NOT NULL DEFAULT 'draft',meta_title TEXT,meta_description TEXT,published_at INTEGER,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS idx_blog_posts_status_published ON blog_posts(status,published_at DESC);
CREATE TABLE IF NOT EXISTS blog_post_offers (post_id TEXT NOT NULL,offer_id TEXT NOT NULL,position INTEGER NOT NULL DEFAULT 0,PRIMARY KEY (post_id,offer_id),FOREIGN KEY (post_id) REFERENCES blog_posts(id) ON DELETE CASCADE,FOREIGN KEY (offer_id) REFERENCES offers(id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS idx_blog_post_offers_post ON blog_post_offers(post_id,position);
CREATE TABLE IF NOT EXISTS blog_post_products (post_id TEXT NOT NULL,id TEXT NOT NULL,name TEXT NOT NULL,brand TEXT,summary TEXT,image_url TEXT,affiliate_url TEXT NOT NULL,price_label TEXT,specs_json TEXT NOT NULL DEFAULT '{}',position INTEGER NOT NULL DEFAULT 0,PRIMARY KEY (post_id,id),FOREIGN KEY (post_id) REFERENCES blog_posts(id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS idx_blog_post_products_post ON blog_post_products(post_id,position);
